long long closestBrute(vector<Point>& p) {
    long long best = LLONG_MAX;
    for (int i = 0; i < (int)p.size(); i++)
        for (int j = i + 1; j < (int)p.size(); j++) {
            long long dx = p[i].x - p[j].x, dy = p[i].y - p[j].y;
            best = min(best, dx * dx + dy * dy);   // squared distance
        }
    return best;   // take the square root only if you need the real value
}

