function closestBrute(p) {
  let best = Infinity;
  for (let i = 0; i < p.length; i++)
    for (let j = i + 1; j < p.length; j++) {
      const dx = p[i][0] - p[j][0], dy = p[i][1] - p[j][1];
      best = Math.min(best, dx * dx + dy * dy);   // squared distance
    }
  return best;   // take the square root only if you need the real value
}
